function designCard(d:RecordData,data:RecordData){const versions=allVersions({artifacts:(data.artifacts||[]).filter((a:RecordData)=>a.designId===d.id)});const latest=versions.at(-1);const builds=(data.implementations||[]).filter((i:RecordData)=>i.designId===d.id);return `<article class="card project-work-card">${d.owner!==me!.pubkey?'<span class="eyebrow">Participant design</span>':''}<h3><a href="#/designs/${e(d.id)}">${e(d.title||'New design')}</a></h3><p class="help">${[d.updatedAt?date(d.updatedAt):'',latest?'Artefact v'+latest.number:'',!d.currentSnapshotId?'Getting started':''].filter(Boolean).map(e).join(' · ')}</p>${d.owner!==me!.pubkey?`<p class="help design-owner">${e(d.ownerLabel||'Project participant')}</p>`:''}<div class="card-actions">${builds.length?`<a class="small" href="#/implementations/${e(builds.at(-1).id)}">Continue build ↗</a>`:''}</div></article>`}
