 modal('Build options',`<p>Choose the design and starting version. Building starts only after you send an instruction.</p><div class="form-grid"><label>Design milestone<select name="snapshotId">${[...snaps].reverse().map((s:RecordData)=>`<option value="${e(s.id)}">Design ${e(s.number)} · ${e(s.title||'Design')}</option>`).join('')}</select></label><label>Starting artefact version<select name="startingVersionId"><option value="">New artefact or imported reference</option>${versions.map(v=>`<option value="${e(v.id)}">${e(v.artifactTitle)} · Version ${e(v.number)}</option>`).join('')}</select></label></div><div class="modal-actions"><button class="primary" type="submit">Open build chat</button></div>`,async form=>{const f=new FormData(form);const i=await api(`/api/designs/${designId}/implementations`,'POST',{snapshotId:f.get('snapshotId'),startingVersionId:f.get('startingVersionId')||null});tab='chat';location.hash=`#/implementations/${i.id}`;});
