function allVersions(data:RecordData):RecordData[]{return (data.artifacts||[]).flatMap((a:RecordData)=>(a.versions||[]).map((v:RecordData)=>({...v,artifactId:a.id,artifactTitle:a.title}))).sort((a:RecordData,b:RecordData)=>new Date(a.createdAt||0).valueOf()-new Date(b.createdAt||0).valueOf())}
const draftKey=(kind:string,id:string)=>`byo-freedom.draft.${kind}.${id}`;
function saveWorkspaceState(){const composer=document.querySelector<HTMLTextAreaElement>('#message-input');if(composer&&current){localStorage.setItem(draftKey(current.implementation?'implementation':'design',current.implementation?.id||current.design.id),composer.value)}const edit=document.querySelector<HTMLTextAreaElement>('#document-editor');if(edit&&current)sessionStorage.setItem(`byo-freedom.edit.${current.design.id}`,edit.value)}
