function collectSiteDraft(){if(!siteDraft)return;const form=document.querySelector<HTMLFormElement>('#site-form');if(!form)return;const f=new FormData(form);siteDraft.title=String(f.get('title')||'');siteDraft.layout=String(f.get('layout'));for(const key of ['logoUrl','primary','background','text','font','buttonStyle','tone','guidance'])siteDraft.brand[key]=String(f.get(`brand.${key}`)||'');siteDraft.homePageId=f.get('homePageId')||null;siteDraft.pages.forEach((page:RecordData)=>{for(const key of ['label','slug','artifactVersionId'])page[key]=String(f.get(`page.${page.id}.${key}`)||'');page.visible=f.has(`page.${page.id}.visible`)});document.querySelectorAll<HTMLOptionElement>('select[name=homePageId] option').forEach(o=>{o.textContent=siteDraft!.pages.find((p:RecordData)=>p.id===o.value)?.label||o.textContent});siteDraft.footerLinks=siteDraft.footerLinks.map((link:RecordData,i:number)=>({label:String(f.get(`footer.${i}.label`)||''),url:String(f.get(`footer.${i}.url`)||'')}));persistSiteDraft();const status=document.querySelector('#site-save-status');if(status)status.textContent='Unsaved changes · kept in this browser';const discard=document.querySelector<HTMLButtonElement>('#site-discard');if(discard)discard.hidden=false;}
async function renderSiteBuilder(id:string,discard=false){if(!me!.admin)throw Error('Admin access is required.');const data=await api(`/api/projects/${id}/site`);const projectData=await api(`/api/projects/${id}`);data.artifacts=projectData.artifacts;data.project=projectData.project;current=projectData;siteState=data;siteDraft=structuredClone(data.draft);if(discard)localStorage.removeItem(siteDraftKey(id));else{try{const saved=JSON.parse(storageGet(siteDraftKey(id))||'null');if(saved&&saved.projectId===id)siteDraft=saved}catch{}}paintSiteBuilder();}
function siteVersionOptions(selected:string){const all=(siteState!.artifacts||[]).filter((a:RecordData)=>!selected||(a.versions||[]).some((v:RecordData)=>v.id===selected)).flatMap((a:RecordData)=>(a.versions||[]).filter((v:RecordData)=>v.validation?.length).map((v:RecordData)=>({...v,artifactTitle:a.title})));return `<option value="">Choose an exact artefact version</option>${all.map((v:RecordData)=>`<option value="${e(v.id)}" ${v.id===selected?'selected':''}>${e(v.artifactTitle)} · v${e(v.number)}${!v.outdatedBrand&&v.brandRevision===siteDraft!.brand.revision?'':' · earlier brand settings'}</option>`).join('')}`}
function paintSiteBuilder(){const d=siteDraft!,state=siteState!,id=d.projectId;const dirty=!!storageGet(siteDraftKey(id));const conflict=d.revision!==state.draft.revision;app.innerHTML=header()+`<main class="shell site-builder">${breadcrumb([['My Projects','/projects'],[state.project?.title||d.title,`/projects/${id}`],['Project Builder']])}${projectNav(id,true)}<div class="heading-row"><div><h1>Project Builder</h1></div><a href="${e(me!.publicOrigin)}/sites/${e(id)}/" target="_blank" rel="noopener" class="small">View public site ↗</a></div><div class="site-status"><span id="site-save-status" role="status">${dirty?'Unsaved changes · kept in this browser':'All changes saved'}</span><span>${state.publishedReleaseId?'Published':'Not published'}</span></div>${conflict?'<div class="error-box" role="alert">A newer draft exists on the server. Your local edits are preserved. Compare them before discarding or restoring them on the latest draft.</div>':''}<form id="site-form"><div class="site-columns"><div class="site-main"><section class="card site-section"><div class="section-row"><div><h2>Pages & navigation</h2><p class="help">Page order sets navigation order. Hidden navigation pages remain public after publication. Removing a page affects the next release; source artefacts and older releases remain.</p></div><button type="button" id="site-add-page" class="small">+ Add page</button></div>${d.pages.length?`<div class="site-pages">${d.pages.map((page:RecordData,i:number)=>`<fieldset class="site-page" aria-label="Page ${i+1}"><div class="site-page-head"><label class="check-label"><input type="radio" name="homePageId" value="${e(page.id)}" ${page.id===d.homePageId?'checked':''}>Homepage</label><div class="row"><button type="button" class="small" data-page-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move page ${i+1} up">↑</button><button type="button" class="small" data-page-move="${i}" data-direction="1" ${i===d.pages.length-1?'disabled':''} aria-label="Move page ${i+1} down">↓</button><button type="button" class="small danger" data-page-remove="${i}">Remove</button></div></div><label>Artefact version<select name="page.${e(page.id)}.artifactVersionId" required>${siteVersionOptions(page.artifactVersionId)}</select></label><div class="site-field-pair"><label>Navigation label<input name="page.${e(page.id)}.label" value="${e(page.label)}" required maxlength="100"></label><label>Page address<input name="page.${e(page.id)}.slug" value="${e(page.slug)}" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="80" spellcheck="false"></label></div><label class="check-label"><input type="checkbox" name="page.${e(page.id)}.visible" ${page.visible?'checked':''}>Show in navigation</label><p class="help site-brand-status">${siteVersionBrandStatus(page.artifactVersionId)}</p></fieldset>`).join('')}</div>`:'<div class="empty"><h3>Give your website its first page.</h3></div>'}</section><section class="card site-section"><h2>Site appearance</h2><div class="site-field-pair"><label>Site title<input name="title" required maxlength="150" value="${e(d.title)}"></label><label>Layout<select name="layout">${[['simple','Simple website'],['resource-library','Resource library'],['event-hub','Event hub']].map(([value,label])=>`<option value="${value}" ${d.layout===value?'selected':''}>${label}</option>`).join('')}</select></label></div></section><section class="card site-section"><div class="section-row"><h2>Footer links</h2><button type="button" id="site-add-footer" class="small">+ Add link</button></div>${d.footerLinks.map((link:RecordData,i:number)=>`<div class="site-footer-row"><label>Label<input name="footer.${i}.label" value="${e(link.label)}" required maxlength="100"></label><label>URL<input name="footer.${i}.url" value="${e(link.url)}" required placeholder="https://… or /sites/…"></label><button type="button" class="small danger" data-footer-remove="${i}" aria-label="Remove footer link ${i+1}">Remove</button></div>`).join('')||''}</section></div><aside class="card site-section site-brand"><h2>Project brand</h2><p class="help">Used by new designs and builds. Rebuild existing pages to apply changes.</p><label>Logo URL<input name="brand.logoUrl" value="${e(d.brand.logoUrl)}" placeholder="https://…" type="url"></label><div class="site-colours">${[['primary','Accent'],['background','Background'],['text','Text']].map(([key,label])=>`<label>${label}<input name="brand.${key}" type="color" value="${e(d.brand[key])}"></label>`).join('')}</div><details class="advanced-brand"><summary>Advanced brand</summary><label>Font family<select name="brand.font">${[['system','System sans serif'],['serif','Serif'],['mono','Monospace']].map(([v,label])=>`<option value="${v}" ${d.brand.font===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Button shape<select name="brand.buttonStyle">${['rounded','square','pill'].map(v=>`<option value="${v}" ${d.brand.buttonStyle===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Tone of voice<textarea name="brand.tone" rows="3" maxlength="1000" placeholder="Clear, welcoming and practical…">${e(d.brand.tone)}</textarea></label><label>Design guidance<textarea name="brand.guidance" rows="6" maxlength="10000" placeholder="Purpose, accessibility, imagery, and rules for new builds…">${e(d.brand.guidance)}</textarea></label></details></aside></div><div class="site-actions"><button class="primary" type="submit">Save draft</button><button type="button" id="site-preview">Private preview</button><button type="button" id="site-publish" class="accent">Publish website</button><button type="button" id="site-discard" class="ghost small" ${dirty?'':'hidden'}>Discard changes</button></div><div id="site-error" role="alert"></div></form><section class="site-section"><div class="section-row"><h2>Publication history</h2></div><div class="design-list">${(state.publications||[]).map((r:RecordData,i:number)=>`<div class="card site-release"><div><strong>${e(r.title||`Site release ${i+1}`)}</strong><p class="help">${e(date(r.createdAt))} · ${r.id===state.publishedReleaseId?'Current':'Saved release'}</p></div><div class="row"><a class="small" href="${e(me!.publicOrigin)}/sites/${e(id)}/releases/${e(r.id)}/" target="_blank" rel="noopener">View release ↗</a>${r.id===state.publishedReleaseId?'':`<button class="small" data-site-rollback="${e(r.id)}">Restore release</button>`}</div></div>`).join('')||''}</div></section></main>`;
document.querySelector('main.site-builder')!.insertAdjacentHTML('beforeend',projectAdmin(state.project));
mountSiteTabs(d,state,collectSiteDraft,persistSiteDraft,paintSiteBuilder,modal);
const form=document.querySelector<HTMLFormElement>('#site-form')!;form.addEventListener('input',collectSiteDraft);form.addEventListener('change',collectSiteDraft);form.addEventListener('submit',ev=>{ev.preventDefault();siteAction(async()=>{await saveSiteDraft();toast('Site draft saved');paintSiteBuilder()})});document.querySelectorAll('[data-page-remove]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();const removed=d.pages.splice(Number(el.getAttribute('data-page-remove')),1)[0];if(removed.id===d.homePageId)d.homePageId=d.pages[0]?.id||null;persistSiteDraft();paintSiteBuilder()}));document.querySelectorAll('[data-page-move]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();const i=Number(el.getAttribute('data-page-move')),j=i+Number(el.getAttribute('data-direction'));[d.pages[i],d.pages[j]]=[d.pages[j],d.pages[i]];persistSiteDraft();paintSiteBuilder()}));document.querySelector('#site-add-footer')!.addEventListener('click',()=>{collectSiteDraft();d.footerLinks.push({label:'',url:''});persistSiteDraft();paintSiteBuilder()});document.querySelectorAll('[data-footer-remove]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();d.footerLinks.splice(Number(el.getAttribute('data-footer-remove')),1);persistSiteDraft();paintSiteBuilder()}));document.querySelector('#site-discard')!.addEventListener('click',()=>modal('Reload the saved draft?',`<p>This discards your browser’s unsaved Site Builder edits and loads the current server draft.</p><div class="modal-actions"><button type="submit" class="primary">Discard local edits & reload</button></div>`,async()=>renderSiteBuilder(id,true)));document.querySelector('#site-preview')!.addEventListener('click',()=>siteAction(async()=>{await saveSiteDraft();paintSiteBuilder();const preview=await api(`/api/projects/${id}/site/preview`,'POST',{expectedRevision:siteDraft!.revision});document.querySelector<HTMLElement>('#site-preview')?.focus();const box=modal('Private site preview',`<iframe class="site-preview-frame" sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer" title="Private site preview"></iframe>`);box.querySelector('.modal')!.classList.add('site-preview-modal');const frame=box.querySelector('iframe')!;frame.addEventListener('load',()=>frame.contentWindow?.postMessage({type:'byo-site-preview',html:preview.html},'*'),{once:true});frame.src=me!.publicOrigin+'/site-preview-host';}));document.querySelector('#site-publish')!.addEventListener('click',()=>siteAction(async()=>{await saveSiteDraft();paintSiteBuilder();const snapshot=structuredClone(siteDraft!);const ids=[...new Set(snapshot.pages.map((p:RecordData)=>p.artifactVersionId))];const requestId=crypto.randomUUID();await api(`/api/projects/${id}/site/publish`,'POST',{expectedRevision:snapshot.revision,requestId,exposeVersionIds:ids});await renderSiteBuilder(id,true)}));document.querySelectorAll('[data-site-rollback]').forEach(el=>el.addEventListener('click',()=>{const releaseId=el.getAttribute('data-site-rollback')!;const requestId=crypto.randomUUID();modal('Restore this release?',`<p>Restore these public pages, navigation and theme. Your private draft stays saved.</p><div class="modal-actions"><button type="submit" class="primary">Restore public release</button></div>`,async()=>{await api(`/api/projects/${id}/site/rollback`,'POST',{releaseId,requestId});await renderSiteBuilder(id);toast('Public release restored')})}));}
function siteVersionBrandStatus(versionId:string){const v=(siteState!.artifacts||[]).flatMap((a:RecordData)=>a.versions||[]).find((v:RecordData)=>v.id===versionId);if(!v)return '';return !v.outdatedBrand&&v.brandRevision===siteState!.draft.brand.revision?'':'Built before the latest brand settings. Rebuild to apply changes; this page keeps its original appearance.'}
async function saveSiteDraft(){collectSiteDraft();const id=siteDraft!.projectId;const saved=await api(`/api/projects/${id}/site`,'PUT',{expectedRevision:siteDraft!.revision,draft:siteDraft});const fresh= saved.draft? saved:await api(`/api/projects/${id}/site`);fresh.artifacts=(await api(`/api/projects/${id}`)).artifacts;siteState={...siteState,...fresh};siteDraft=structuredClone(siteState!.draft);localStorage.removeItem(siteDraftKey(id));}
async function siteAction(fn:()=>Promise<any>){await act(async()=>{try{await fn()}catch(err){const box=document.querySelector('#site-error');if(box){box.className='error-box';box.textContent=(err as any).status===409?'The server draft changed. Your edits are preserved in this browser. Reload the saved draft only when you are ready to discard or compare them.':(err as Error).message}throw err}})}
async function designBrandExceptions(designId:string){const brand=await api(`/api/designs/${designId}/brand`);modal('Design brand exceptions',`<label>Explicit exceptions<textarea name="exceptions" rows="6" maxlength="8000" placeholder="Leave empty to inherit the project brand fully.">${e(brand.exceptions)}</textarea></label><div class="modal-actions"><button type="submit" class="primary">Save exceptions</button></div>`,async form=>{await api(`/api/designs/${designId}/brand`,'PATCH',{expectedRevision:brand.revision,exceptions:String(new FormData(form).get('exceptions')||'')});toast('Design brand exceptions saved')})}

async function renderInstalledApp(versionId:string){const token=generation;const launch=await api(`/api/installed-apps/${encodeURIComponent(versionId)}`);if(token!==generation)return;app.innerHTML=header()+`<main class="shell"><div>${breadcrumb([['My Projects','/projects'],[launch.project.title,`/projects/${launch.project.id}`],[launch.title]])}</div><div class="heading-row"><div><h1>${e(launch.title)}</h1><p class="help">Version ${e(launch.number)} · Live saved data · Project members only</p></div></div><p class="help">This app can’t see your signer or private design conversations.</p><iframe class="site-preview-frame" id="installed-app-frame" title="${e(launch.title)} — saved app data" sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer"></iframe></main>`;const frame=document.querySelector<HTMLIFrameElement>('#installed-app-frame')!;attachNStackBridge(frame,launch.versionId,api,'live',nstackSigner());frame.src=launch.previewUrl;}
async function route(){updateActiveBuildReadiness=null;await identityReady;saveWorkspaceState();chatComposing=false;generation++;clearTimeout(pollTimer);activeRoute='';lastRenderKey='';selectedSnapshot=null;selectedVersion=null;editing=false;const path=location.hash.replace(/^#/,'')||'/projects';const bits=path.split('/');if(bits[1]==='designs'||bits[1]==='implementations'){try{const selection=JSON.parse(sessionGet(`byo-freedom.selection.${bits[1]==='designs'?'design':'implementation'}.${bits[2]}`)||'null');selectedSnapshot=selection?.snapshotId||null;selectedVersion=selection?.versionId||null}catch{}}if(!identity.active){if(/^\/apps\/[^/?#]+$/.test(path))try{sessionStorage.setItem('byo-freedom.return-app',path);}catch{}renderEntry();return}if(!me){try{await loadMe()}catch(err){renderEntry();fail(err);return}}try{if(sessionGet(INVITE_KEY)){if(pendingJoinName()&&!pendingJoinName()!.pubkey){await renderWorkshopEntry();return;}try{const destination=await joinPendingInvite();if(destination){history.replaceState(null,'','/'+destination);await renderProject(destination.split('/')[2]);return}}catch(err){app.innerHTML=header()+`<main class="standalone-error"><h1>We couldn’t join that project.</h1><p class="muted">${e((err as Error).message)}</p><p>Your invitation is saved. Check the code with the organiser or retry if signing or the connection failed.</p><div class="row"><button data-action="retry-invite">Retry invitation</button><button data-action="dismiss-invite">Enter a code manually</button></div></main>`;return}}if(/^\/apps\/[^/]+$/.test(path))await renderInstalledApp(path.split('/')[2]);else if(path==='/profile')await profile();else if(/^\/projects\/[^/]+\/site$/.test(path))await renderSiteBuilder(path.split('/')[2]);else if(/^\/projects\/[^/]+$/.test(path))await renderProject(path.split('/')[2]);else if(/^\/designs\/[^/]+$/.test(path))await workspace('design',path.split('/')[2]);else if(/^\/implementations\/[^/]+$/.test(path))await workspace('implementation',path.split('/')[2]);else await renderProjects()}catch(err){app.innerHTML=header()+`<main class="standalone-error"><h1>We couldn’t open this page.</h1><p role="alert">Your saved work is still available. Check your access or connection, then try again.</p><details><summary>Error details</summary><p>${e((err as Error).message)}</p></details><a href="#/projects">Back to My Projects</a></main>`}}
document.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!el)return;const action=el.dataset.action;act(async()=>{switch(action){case 'retry-invite':await route();break;case 'dismiss-invite':sessionStorage.removeItem('byo-freedom.join-name');sessionStorage.removeItem(INVITE_KEY);history.replaceState(null,'','/#/projects');await route();break;case 'share-project':await shareProject();break;case 'nstack-settings':await nstackSettings(api,modal,nstackSigner());break;case 'anon':await login('anon');break;case 'extension':await login('extension');break;case 'import':restore();break;case 'profile':location.hash='#/profile';break;case 'projects':location.hash='#/projects';break;case 'export':await exportKey();break;case 'logout':saveWorkspaceState();identity.signOut();me=null;clearTimeout(pollTimer);activeRoute='';renderEntry();break;case 'new-project':createProject();break;case 'featured':featured();break;case 'new-design':await newDesign();break;case 'project-settings':projectSettings();break;case 'delete-project':deleteProject();break;case 'design-brand':await designBrandExceptions(current!.design.id);break;case 'install-examples':await installExamples();break;case 'workshop-starters':await workshopExamples();break;case 'workshop-summary':await summaryCheckpoint();break;case 'implement-current':await buildNow();break;case 'build-options':await buildOptions();break;case 'latest-design':selectedSnapshot=null;selectedVersion=null;await workspace('design',current!.design.id);break;case 'rename':await saveEdit(true);break;case 'edit-document':selectedVersion=null;sessionStorage.setItem(`byo-freedom.edit-base.${current!.design.id}`,JSON.stringify({snapshotId:current!.design.currentSnapshotId||null,title:current!.design.title}));editing=true;await workspace('design',current!.design.id);break;case 'cancel-edit':editing=false;await workspace('design',current!.design.id);break;case 'save-edit':await saveEdit();break;}})});
document.addEventListener('byo-image-drafts',ev=>{if((ev as CustomEvent).detail===current?.design?.id)updateActiveBuildReadiness?.();});
window.addEventListener('hashchange',()=>route());window.addEventListener('beforeunload',saveWorkspaceState);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&activeRoute){const [kind,id]=activeRoute.split('/');workspace(kind,id,true).catch(fail)}});route();

window.addEventListener('storage',event=>{if(event.key==='byo-freedom.signed-out.v1'||event.key===MODE){me=null;void route();}});

function resizeWorkshopViewport(){const height=window.visualViewport?.height||window.innerHeight;document.documentElement.style.setProperty('--workshop-viewport-height',`${height}px`);document.documentElement.classList.toggle('workshop-compact',height<600&&window.innerWidth<=700);}
window.visualViewport?.addEventListener('resize',resizeWorkshopViewport);
window.addEventListener('resize',resizeWorkshopViewport);resizeWorkshopViewport();
